// Package quizstreak is a multiple-choice trivia quiz where every player
// runs their own independent streak instead of racing others for a single
// shared question.
//
// Each address gets its own current question, picked deterministically from
// the address and the block height of its first answer so different players
// don't all start on the same question. A correct answer extends the
// player's streak and advances them to their next question; a wrong answer
// breaks the streak back to zero but leaves the same question live so they
// can retry. The realm tracks each player's best-ever streak on a global
// leaderboard.
package quizstreak

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// question is one fixed trivia entry.
type question struct {
	text       string
	choices    [4]string
	correctIdx int
}

// playerState is one address's progress through the question bank.
type playerState struct {
	qIdx    int
	streak  int
	best    int
	correct int
	wrong   int
}

var (
	questions = []question{
		{"What is the smallest prime number?", [4]string{"0", "1", "2", "3"}, 2},
		{"Which gas does a plant primarily absorb for photosynthesis?", [4]string{"Oxygen", "Nitrogen", "Carbon dioxide", "Hydrogen"}, 2},
		{"How many continents are there on Earth?", [4]string{"5", "6", "7", "8"}, 2},
		{"In binary, what is 1 + 1?", [4]string{"2", "10", "11", "0"}, 1},
		{"What does 'HTTP' stand for?", [4]string{"HyperText Transfer Protocol", "High Transfer Text Protocol", "Home Tool Transfer Protocol", "HyperText Transmission Path"}, 0},
		{"Which planet is known as the Red Planet?", [4]string{"Venus", "Jupiter", "Mars", "Saturn"}, 2},
		{"What is the time complexity of binary search?", [4]string{"O(n)", "O(log n)", "O(n^2)", "O(1)"}, 1},
		{"Which ocean is the largest by surface area?", [4]string{"Atlantic", "Indian", "Arctic", "Pacific"}, 3},
		{"What does 'CPU' stand for?", [4]string{"Central Processing Unit", "Computer Personal Unit", "Central Program Utility", "Core Processing Unicode"}, 0},
		{"How many bits are in a byte?", [4]string{"4", "8", "16", "32"}, 1},
	}

	players = avl.NewTree() // addr(string) -> *playerState
)

// startIndex picks a deterministic starting question for a brand-new player,
// spreading players across the bank using their address and the height of
// their first answer as entropy.
func startIndex(addr string, height int64) int {
	if height < 0 {
		height = -height
	}
	var sum int64
	for i := 0; i < len(addr); i++ {
		sum += int64(addr[i])
	}
	n := int64(len(questions))
	return int((sum + height) % n)
}

// getPlayer returns addr's state, lazily creating it on first contact.
func getPlayer(addr string) *playerState {
	if v, ok := players.Get(addr).(*playerState); ok {
		return v
	}
	p := &playerState{qIdx: startIndex(addr, runtime.ChainHeight())}
	players.Set(addr, p)
	return p
}

// nextIndex advances a solved player to a fresh-feeling next question: the
// step grows with the streak so a long run doesn't loop through the bank in
// a visibly fixed order.
func nextIndex(cur, streak, n int) int {
	return (cur + 1 + streak) % n
}

// Answer submits a choice (0..3) for the caller's current question.
// Crossing function: caller invokes as Answer(cross(cur), choiceIdx).
func Answer(cur realm, choiceIdx int) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if choiceIdx < 0 || choiceIdx >= len(questions[0].choices) {
		panic("choice must be in 0..3")
	}

	addr := cur.Previous().Address().String()
	p := getPlayer(addr)
	q := questions[p.qIdx]

	if choiceIdx != q.correctIdx {
		brokeStreak := p.streak
		p.streak = 0
		p.wrong++
		if brokeStreak > 0 {
			return "Wrong — streak of " + strconv.Itoa(brokeStreak) + " broken. Same question stays live, try again."
		}
		return "Wrong — try again."
	}

	p.streak++
	p.correct++
	if p.streak > p.best {
		p.best = p.streak
	}
	p.qIdx = nextIndex(p.qIdx, p.streak, len(questions))

	chain.Emit("QuizAnswered",
		"player", addr,
		"streak", strconv.Itoa(p.streak),
		"best", strconv.Itoa(p.best),
	)

	return "Correct! Streak is now " + strconv.Itoa(p.streak) + ". Next question is live."
}

// leaderboardEntry is a snapshot row used only for rendering, sorted by best
// streak descending.
type leaderboardEntry struct {
	addr string
	best int
}

func leaderboard() []leaderboardEntry {
	var rows []leaderboardEntry
	players.Iterate("", "", func(addr string, v any) bool {
		rows = append(rows, leaderboardEntry{addr: addr, best: v.(*playerState).best})
		return false
	})
	for i := 1; i < len(rows); i++ {
		j := i
		for j > 0 && rows[j-1].best < rows[j].best {
			rows[j-1], rows[j] = rows[j], rows[j-1]
			j--
		}
	}
	return rows
}

func renderQuestion(b *strings.Builder, p *playerState) {
	q := questions[p.qIdx]
	letters := [4]string{"A", "B", "C", "D"}
	b.WriteString("**" + q.text + "**\n\n")
	for i, c := range q.choices {
		b.WriteString("- **" + letters[i] + "** (" + strconv.Itoa(i) + "): " + c + "\n")
	}
	b.WriteString("\n- Current streak: " + strconv.Itoa(p.streak) + "\n")
	b.WriteString("- Best streak: " + strconv.Itoa(p.best) + "\n")
	b.WriteString("- Correct / wrong lifetime: " + strconv.Itoa(p.correct) + " / " + strconv.Itoa(p.wrong) + "\n\n")
}

// Render produces the gnoweb Markdown view. The root path shows the rules
// and the leaderboard; a path of a bech32 address shows that player's
// current question and stats.
func Render(path string) string {
	var b strings.Builder

	b.WriteString("# Quiz Streak\n\n")
	b.WriteString("Everyone plays their own trivia run at their own pace. Call ")
	b.WriteString("`Answer(choiceIdx)` with 0-3 — a correct answer extends your streak ")
	b.WriteString("and moves you to your next question; a wrong answer breaks your ")
	b.WriteString("streak but leaves the same question live so you can retry.\n\n")

	if path != "" {
		if v, ok := players.Get(path).(*playerState); ok {
			b.WriteString("## Your question (`" + path + "`)\n\n")
			renderQuestion(&b, v)
		} else {
			b.WriteString("## `" + path + "`\n\n_No answers submitted yet — call `Answer` to get your first question._\n\n")
		}
	}

	b.WriteString("## Best-streak leaderboard\n\n")
	rows := leaderboard()
	if len(rows) == 0 {
		b.WriteString("_No one has played yet — be the first!_\n\n")
	} else {
		b.WriteString("| Player | Best streak |\n|---|---|\n")
		for _, r := range rows {
			b.WriteString("| `" + r.addr + "` | " + strconv.Itoa(r.best) + " |\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("## How to play\n\n")
	b.WriteString("```\n")
	b.WriteString("gnokey maketx call -pkgpath gno.land/r/g12cs4cehujpffpjpywmkqj43m6u5ya53nj69sjz/quizstreak \\\n")
	b.WriteString("  -func Answer -args <0|1|2|3> ...\n")
	b.WriteString("```\n\n")
	b.WriteString("View your own dashboard at `.../quizstreak:<your-address>`.\n")

	return b.String()
}

package position

import (
	"errors"
	"time"

	u256 "gno.land/p/gnoswap/uint256"
	ufmt "gno.land/p/nt/ufmt/v0"

	prbac "gno.land/p/gnoswap/rbac"
	"gno.land/r/gnoswap/access"
)

// assertIsNotExpired panics if the deadline is expired.
func assertIsNotExpired(deadline int64) {
	now := time.Now().Unix()

	if now > deadline {
		panic(makeErrorWithDetails(
			errExpired,
			ufmt.Sprintf("transaction too old, now(%d) > deadline(%d)", now, deadline),
		))
	}
}

// assertValidNumberString panics if the input string does not represent a valid integer.
func assertValidNumberString(input string) {
	if len(input) == 0 {
		panic(newErrorWithDetail(errInvalidInput, "input is empty"))
	}

	bytes := []byte(input)
	for i, b := range bytes {
		if i == 0 && b == '-' {
			continue // Allow if the first character is a negative sign (-)
		}
		if b < '0' || b > '9' {
			panic(newErrorWithDetail(
				errInvalidInput,
				ufmt.Sprintf("input string : %s", input)))
		}
	}
}

// assertValidLiquidityAmount panics if the liquidity amount is zero.
func assertValidLiquidityAmount(liquidity string) {
	if u256.MustFromDecimal(liquidity).IsZero() {
		panic(newErrorWithDetail(
			errZeroLiquidity,
			ufmt.Sprintf("liquidity amount must be greater than 0, got %s", liquidity),
		))
	}
}

// assertExistsPosition panics if the position does not exist.
func assertExistsPosition(p *positionV1, positionId uint64) {
	if !p.exists(positionId) {
		panic(newErrorWithDetail(
			errPositionDoesNotExist,
			ufmt.Sprintf("position with position ID(%d) doesn't exist", positionId),
		))
	}
}

// assertIsOwnerForToken panics if caller is not the owner of the position.
func assertIsOwnerForToken(p *positionV1, positionId uint64, caller address) {
	assertExistsPosition(p, positionId)

	if !p.isOwner(positionId, caller) {
		panic(newErrorWithDetail(
			errNoPermission,
			ufmt.Sprintf("caller(%s) is not owner of positionId(%d)", caller, positionId),
		))
	}
}

// assertIsOwnerOrOperatorForToken panics if caller is not the owner or operator of the position.
func assertIsOwnerOrOperatorForToken(p *positionV1, positionId uint64, caller address) {
	assertExistsPosition(p, positionId)

	if !p.isOwnerOrOperator(positionId, caller) {
		panic(newErrorWithDetail(
			errNoPermission,
			ufmt.Sprintf("caller(%s) is not owner or approved operator of positionId(%d)", caller, positionId),
		))
	}
}

// assertEqualsAddress panics if addresses are invalid or not equal.
func assertEqualsAddress(prevAddr, otherAddr address) {
	access.AssertIsValidAddress(prevAddr)
	access.AssertIsValidAddress(otherAddr)

	if prevAddr != otherAddr {
		panic(newErrorWithDetail(
			errInvalidAddress,
			ufmt.Sprintf("(%s, %s)", prevAddr, otherAddr),
		))
	}
}

// assertValidOperatorAddress validates operator address.
// Empty address is allowed (for operator removal), but non-empty addresses must be valid.
func assertValidOperatorAddress(operator address) {
	if operator != address("") && !operator.IsValid() {
		panic(newErrorWithDetail(errInvalidAddress, ufmt.Sprintf("operator(%s)", operator)))
	}
}

// assertIsNotMintToStaker panics if the mintTo address is staker.
func assertIsNotMintToStaker(mintTo address) {
	stakerAddr := access.MustGetAddress(prbac.ROLE_STAKER.String())
	if mintTo == stakerAddr {
		panic(errors.New(errCannotMintToStaker))
	}
}

package position

import (
	"errors"
	"gno.land/p/gnoswap/consts"
	"gno.land/p/gnoswap/gnsmath"
	prabc "gno.land/p/gnoswap/rbac"
	u256 "gno.land/p/gnoswap/uint256"
	"gno.land/p/gnoswap/utils"
	ufmt "gno.land/p/nt/ufmt/v0"

	"gno.land/r/gnoswap/access"
	"gno.land/r/gnoswap/common"
	pl "gno.land/r/gnoswap/pool"
	"gno.land/r/gnoswap/position"
)

// decreaseLiquidity reduces position liquidity and collects fees.
// Returns positionId, liquidity, fee0, fee1, amount0, amount1, poolPath.
func (p *positionV1) decreaseLiquidity(_ int, rlm realm, params DecreaseLiquidityParams) (uint64, string, string, string, string, string, string, error) {
	caller := params.caller

	// before decrease liquidity, collect fee first
	_, fee0Str, fee1Str, _, _, _ := p.collectFee(0, rlm, params.positionId, params.caller)

	position := p.mustGetPosition(params.positionId)
	positionLiquidity := u256.MustFromDecimal(position.Liquidity())
	if positionLiquidity.IsZero() {
		return params.positionId,
			"",
			fee0Str,
			fee1Str,
			"", "",
			position.PoolKey(),
			makeErrorWithDetails(
				errZeroLiquidity,
				ufmt.Sprintf("position(position ID:%d) has 0 liquidity", params.positionId),
			)
	}

	liquidityToRemove := u256.MustFromDecimal(params.liquidity)

	if liquidityToRemove.Gt(positionLiquidity) {
		return params.positionId,
			liquidityToRemove.ToString(),
			fee0Str,
			fee1Str,
			"", "",
			position.PoolKey(),
			makeErrorWithDetails(
				errInvalidLiquidity,
				ufmt.Sprintf("Liquidity requested(%s) is greater than liquidity held(%s)", liquidityToRemove.ToString(), positionLiquidity.ToString()),
			)
	}

	pToken0, pToken1, pFee := splitOf(position.PoolKey())
	burn0, burn1 := pl.Burn(cross(rlm), pToken0, pToken1, pFee, position.TickLower(), position.TickUpper(), liquidityToRemove.ToString(), caller)

	burnedAmount0 := utils.SafeParseInt64(burn0)
	burnedAmount1 := utils.SafeParseInt64(burn1)

	if burnedAmount0 < 0 || burnedAmount1 < 0 {
		panic(errors.New(errUnderflow))
	}

	positionKey := computePositionKey(position.TickLower(), position.TickUpper())
	feeGrowthInside0LastX128Str, feeGrowthInside1LastX128Str := pl.GetPositionFeeGrowthInsideLastX128(position.PoolKey(), positionKey)

	// Add only burned amounts to tokensOwed since fees were already collected and processed in collectFee
	tokensOwed0 := gnsmath.SafeAddInt64(position.TokensOwed0(), burnedAmount0)
	tokensOwed1 := gnsmath.SafeAddInt64(position.TokensOwed1(), burnedAmount1)

	newLiquidity, underflow := u256.Zero().SubOverflow(positionLiquidity, liquidityToRemove)
	if underflow {
		panic(newErrorWithDetail(errUnderflow, "positionLiquidity - liquidityToRemove underflow"))
	}

	position.SetTokensOwed0(tokensOwed0)
	position.SetTokensOwed1(tokensOwed1)
	position.SetFeeGrowthInside0LastX128(feeGrowthInside0LastX128Str)
	position.SetFeeGrowthInside1LastX128(feeGrowthInside1LastX128Str)
	position.SetLiquidity(newLiquidity.ToString())

	p.mustUpdatePosition(0, rlm, params.positionId, *position)

	collect0, collect1 := pl.Collect(
		cross(rlm),
		pToken0,
		pToken1,
		pFee,
		caller,
		position.TickLower(),
		position.TickUpper(),
		burn0,
		burn1,
	)

	collectAmount0 := u256.MustFromDecimal(collect0)
	collectAmount1 := u256.MustFromDecimal(collect1)

	// Slippage check on actually collected amounts to ensure user receives minimum expected tokens
	if isSlippageExceeded(collectAmount0, collectAmount1, params.amount0Min, params.amount1Min) {
		return params.positionId,
			liquidityToRemove.ToString(),
			fee0Str,
			fee1Str,
			collect0,
			collect1,
			position.PoolKey(),
			makeErrorWithDetails(
				errSlippage,
				ufmt.Sprintf("collectAmount0(%s) >= amount0Min(%s) && collectAmount1(%s) >= amount1Min(%s)",
					collectAmount0.ToString(),
					params.amount0Min.ToString(),
					collectAmount1.ToString(),
					params.amount1Min.ToString(),
				),
			)
	}

	poolAddr := access.MustGetAddress(prabc.ROLE_POOL.String())

	// Check for underflow when subtracting collected amounts from tokens owed
	collectAmount0Int64 := gnsmath.SafeConvertToInt64(collectAmount0)
	collectAmount1Int64 := gnsmath.SafeConvertToInt64(collectAmount1)

	if position.TokensOwed0() < collectAmount0Int64 {
		panic(ufmt.Sprintf("[POSITION] burn.gno | collect() | tokensOwed0(%d) < collectAmount0(%d)", position.TokensOwed0(), collectAmount0Int64))
	}
	position.SetTokensOwed0(gnsmath.SafeSubInt64(position.TokensOwed0(), collectAmount0Int64))

	if position.TokensOwed1() < collectAmount1Int64 {
		panic(ufmt.Sprintf("[POSITION] burn.gno | collect() | tokensOwed1(%d) < collectAmount1(%d)", position.TokensOwed1(), collectAmount1Int64))
	}
	position.SetTokensOwed1(gnsmath.SafeSubInt64(position.TokensOwed1(), collectAmount1Int64))

	if position.IsClear() {
		position.SetBurned(true) // just update flag (we don't want to burn actual position)
	}

	p.mustUpdatePosition(0, rlm, params.positionId, *position)

	common.SafeGRC20TransferFrom(cross(rlm), pToken0, poolAddr, caller, collectAmount0Int64)
	common.SafeGRC20TransferFrom(cross(rlm), pToken1, poolAddr, caller, collectAmount1Int64)

	return params.positionId, liquidityToRemove.ToString(), fee0Str, fee1Str, collect0, collect1, position.PoolKey(), nil
}

// calculateFees calculates the fees for the current position.
func (p *positionV1) calculateFees(position *position.Position, currentFeeGrowth FeeGrowthInside) (int64, int64) {
	posLiquidity := u256.MustFromDecimal(position.Liquidity())
	fee0 := calculateTokensOwed(
		currentFeeGrowth.feeGrowthInside0LastX128,
		u256.MustFromDecimal(position.FeeGrowthInside0LastX128()),
		posLiquidity,
	)

	fee1 := calculateTokensOwed(
		currentFeeGrowth.feeGrowthInside1LastX128,
		u256.MustFromDecimal(position.FeeGrowthInside1LastX128()),
		posLiquidity,
	)

	return gnsmath.SafeAddInt64(position.TokensOwed0(), gnsmath.SafeConvertToInt64(fee0)), gnsmath.SafeAddInt64(position.TokensOwed1(), gnsmath.SafeConvertToInt64(fee1))
}

func calculateTokensOwed(
	feeGrowthInsideLastX128 *u256.Uint,
	positionFeeGrowthInsideLastX128 *u256.Uint,
	positionLiquidity *u256.Uint,
) *u256.Uint {
	diff := u256.Zero().Sub(feeGrowthInsideLastX128, positionFeeGrowthInsideLastX128)
	return u256.MulDiv(diff, positionLiquidity, consts.Q128())
}

// package v1 manages liquidity positions as NFTs in GnoSwap pools.
//
// Each position is represented as a non-transferable GRC721 NFT with concentrated
// liquidity within a specific tick range. The package handles position lifecycle
// including minting, liquidity adjustments, fee collection, and repositioning.
package position

package position

import (
	ufmt "gno.land/p/nt/ufmt/v0"
)

const (
	errNoPermission         = "[GNOSWAP-POSITION-001] caller has no permission"
	errSlippage             = "[GNOSWAP-POSITION-002] slippage failed"
	errInvalidTokenPath     = "[GNOSWAP-POSITION-003] invalid token address"
	errInvalidInput         = "[GNOSWAP-POSITION-004] invalid input data"
	errDataNotFound         = "[GNOSWAP-POSITION-005] requested data not found"
	errExpired              = "[GNOSWAP-POSITION-006] transaction expired"
	errInvalidLiquidity     = "[GNOSWAP-POSITION-007] invalid liquidity"
	errNotClear             = "[GNOSWAP-POSITION-008] position is not clear"
	errZeroLiquidity        = "[GNOSWAP-POSITION-009] zero liquidity"
	errPositionExist        = "[GNOSWAP-POSITION-010] position with same positionId already exists"
	errInvalidAddress       = "[GNOSWAP-POSITION-011] invalid address"
	errPositionDoesNotExist = "[GNOSWAP-POSITION-012] position does not exist"
	errUnderflow            = "[GNOSWAP-POSITION-013] underflow"
	errOverflow             = "[GNOSWAP-POSITION-014] overflow"
	errCannotMintToStaker   = "[GNOSWAP-POSITION-015] cannot mint to staker"
	errSpoofedRealm         = "[GNOSWAP-POSITION-016] rlm does not match the current crossing frame"
)

// newErrorWithDetail appends additional context or details to an existing error message.
func newErrorWithDetail(message string, detail string) string {
	return ufmt.Errorf("%s || %s", message, detail).Error()
}

// makeErrorWithDetails creates an error with additional context.
func makeErrorWithDetails(message string, details string) error {
	return ufmt.Errorf("%s || %s", message, details)
}

package position

import (
	"strconv"

	"gno.land/p/gnoswap/consts"
	u256 "gno.land/p/gnoswap/uint256"
	ufmt "gno.land/p/nt/ufmt/v0"

	pl "gno.land/r/gnoswap/pool"
	"gno.land/r/gnoswap/position"
)

// MustGetPosition returns a position for a given position ID.
// panics if position doesn't exist
func (p *positionV1) mustGetPosition(positionId uint64) *position.Position {
	pos, exist := p.GetPosition(positionId)
	if !exist {
		panic(newErrorWithDetail(
			errPositionDoesNotExist,
			ufmt.Sprintf("position with position ID(%d) doesn't exist", positionId),
		))
	}

	return &pos
}

// GetPositionCount returns the total number of positions.
func (p *positionV1) GetPositionCount() int {
	return p.store.GetPositions().Size()
}

// GetPositionIDs returns a paginated list of position IDs.
func (p *positionV1) GetPositionIDs(offset, count int) []uint64 {
	positions := p.store.GetPositions()
	positionIDs := make([]uint64, 0)

	positions.IterateByOffset(offset, count, func(key string, _ any) bool {
		id, err := strconv.ParseUint(key, 10, 64)
		if err != nil {
			return false
		}

		positionIDs = append(positionIDs, id)

		return false
	})

	return positionIDs
}

// GetPosition returns a position for a given position ID.
// Returns false if position doesn't exist
func (p *positionV1) GetPosition(id uint64) (position.Position, bool) {
	return p.store.GetPosition(id)
}

// ExistPosition checks if a position exists for a given position ID
func (p *positionV1) ExistPosition(positionId uint64) bool {
	return p.store.HasPosition(positionId)
}

func (p *positionV1) IsBurned(positionId uint64) bool {
	return p.mustGetPosition(positionId).Burned()
}

func (p *positionV1) IsInRange(positionId uint64) bool {
	position := p.mustGetPosition(positionId)
	poolPath := position.PoolKey()
	poolCurrentTick := pl.GetSlot0Tick(poolPath)

	return position.TickLower() <= poolCurrentTick && poolCurrentTick < position.TickUpper()
}

func (p *positionV1) GetPositionOperator(positionId uint64) address {
	return p.mustGetPosition(positionId).Operator()
}

func (p *positionV1) GetPositionPoolKey(positionId uint64) string {
	return p.mustGetPosition(positionId).PoolKey()
}

func (p *positionV1) GetPositionTickLower(positionId uint64) int32 {
	return p.mustGetPosition(positionId).TickLower()
}

func (p *positionV1) GetPositionTickUpper(positionId uint64) int32 {
	return p.mustGetPosition(positionId).TickUpper()
}

func (p *positionV1) GetPositionLiquidity(positionId uint64) string {
	return p.mustGetPosition(positionId).Liquidity()
}

func (p *positionV1) GetPositionTokenBalances(positionId uint64) (int64, int64) {
	position := p.mustGetPosition(positionId)

	return calculatePositionBalances(position)
}

func (p *positionV1) GetPositionFeeGrowthInside0LastX128(positionId uint64) string {
	return p.mustGetPosition(positionId).FeeGrowthInside0LastX128()
}

func (p *positionV1) GetPositionFeeGrowthInside1LastX128(positionId uint64) string {
	return p.mustGetPosition(positionId).FeeGrowthInside1LastX128()
}

func (p *positionV1) GetPositionTokensOwed0(positionId uint64) int64 {
	return p.mustGetPosition(positionId).TokensOwed0()
}

func (p *positionV1) GetPositionTokensOwed1(positionId uint64) int64 {
	return p.mustGetPosition(positionId).TokensOwed1()
}

func (p *positionV1) GetPositionOwner(positionId uint64) address {
	owner, err := p.nftAccessor.OwnerOf(positionIdFrom(positionId))
	if err != nil {
		panic(newErrorWithDetail(
			errDataNotFound, err.Error()))
	}

	return owner
}

func (p *positionV1) GetUnclaimedFee(positionId uint64) (*u256.Uint, *u256.Uint) {
	// ref: https://blog.uniswap.org/uniswap-v3-math-primer-2#calculating-uncollected-fees
	position := p.mustGetPosition(positionId)

	liquidity := u256.MustFromDecimal(position.Liquidity())
	tickLower := position.TickLower()
	tickUpper := position.TickUpper()

	poolKey := position.PoolKey()

	currentTick := pl.GetSlot0Tick(poolKey)

	feeGrowthGlobal0X128Str, feeGrowthGlobal1X128Str := pl.GetFeeGrowthGlobalX128(poolKey)
	feeGrowthGlobal0X128 := u256.MustFromDecimal(feeGrowthGlobal0X128Str)
	feeGrowthGlobal1X128 := u256.MustFromDecimal(feeGrowthGlobal1X128Str)

	tickUpperFeeGrowthOutside0X128Str, tickUpperFeeGrowthOutside1X128Str := pl.GetTickFeeGrowthOutsideX128(poolKey, tickUpper)
	tickUpperFeeGrowthOutside0X128 := u256.MustFromDecimal(tickUpperFeeGrowthOutside0X128Str)
	tickUpperFeeGrowthOutside1X128 := u256.MustFromDecimal(tickUpperFeeGrowthOutside1X128Str)

	tickLowerFeeGrowthOutside0X128Str, tickLowerFeeGrowthOutside1X128Str := pl.GetTickFeeGrowthOutsideX128(poolKey, tickLower)
	tickLowerFeeGrowthOutside0X128 := u256.MustFromDecimal(tickLowerFeeGrowthOutside0X128Str)
	tickLowerFeeGrowthOutside1X128 := u256.MustFromDecimal(tickLowerFeeGrowthOutside1X128Str)

	feeGrowthInside0LastX128 := u256.MustFromDecimal(position.FeeGrowthInside0LastX128())
	feeGrowthInside1LastX128 := u256.MustFromDecimal(position.FeeGrowthInside1LastX128())

	var tickLowerFeeGrowthBelow0, tickLowerFeeGrowthBelow1, tickUpperFeeGrowthAbove0, tickUpperFeeGrowthAbove1 *u256.Uint

	if currentTick >= tickUpper {
		tickUpperFeeGrowthAbove0 = u256.Zero().Sub(feeGrowthGlobal0X128, tickUpperFeeGrowthOutside0X128)
		tickUpperFeeGrowthAbove1 = u256.Zero().Sub(feeGrowthGlobal1X128, tickUpperFeeGrowthOutside1X128)
	} else {
		tickUpperFeeGrowthAbove0 = tickUpperFeeGrowthOutside0X128
		tickUpperFeeGrowthAbove1 = tickUpperFeeGrowthOutside1X128
	}

	if currentTick >= tickLower {
		tickLowerFeeGrowthBelow0 = tickLowerFeeGrowthOutside0X128
		tickLowerFeeGrowthBelow1 = tickLowerFeeGrowthOutside1X128
	} else {
		tickLowerFeeGrowthBelow0 = u256.Zero().Sub(feeGrowthGlobal0X128, tickLowerFeeGrowthOutside0X128)
		tickLowerFeeGrowthBelow1 = u256.Zero().Sub(feeGrowthGlobal1X128, tickLowerFeeGrowthOutside1X128)
	}

	feeGrowthInside0X128 := u256.Zero().Sub(feeGrowthGlobal0X128, tickLowerFeeGrowthBelow0)
	feeGrowthInside0X128 = u256.Zero().Sub(feeGrowthInside0X128, tickUpperFeeGrowthAbove0)

	feeGrowthInside1X128 := u256.Zero().Sub(feeGrowthGlobal1X128, tickLowerFeeGrowthBelow1)
	feeGrowthInside1X128 = u256.Zero().Sub(feeGrowthInside1X128, tickUpperFeeGrowthAbove1)

	diffGrowthInside0X128 := u256.Zero().Sub(feeGrowthInside0X128, feeGrowthInside0LastX128)
	unclaimedFee0 := u256.MulDiv(diffGrowthInside0X128, liquidity, consts.Q128())

	diffGrowthInside1X128 := u256.Zero().Sub(feeGrowthInside1X128, feeGrowthInside1LastX128)
	unclaimedFee1 := u256.MulDiv(diffGrowthInside1X128, liquidity, consts.Q128())
	return unclaimedFee0, unclaimedFee1
}

package position

import (
	"errors"
	"gno.land/r/gnoswap/position"
)

func init(cur realm) {
	registerPositionV1(cur)
}

func registerPositionV1(cur realm) {
	position.RegisterInitializer(
		cross(cur),
		func(_ int, rlm realm, positionStore position.IPositionStore) position.IPosition {
			if !rlm.IsCurrent() {
				panic(errors.New(errSpoofedRealm))
			}

			err := initStoreData(0, rlm, positionStore)
			if err != nil {
				panic(err)
			}

			return NewPositionV1(positionStore, newGNFTAccessor())
		},
	)
}

func initStoreData(_ int, rlm realm, positionStore position.IPositionStore) error {
	if !positionStore.HasPositionNextIDStoreKey() {
		err := positionStore.SetPositionNextID(0, rlm, uint64(1))
		if err != nil {
			return err
		}
	}

	if !positionStore.HasPositionsStoreKey() {
		err := positionStore.SetPositions(0, rlm, position.NewPositionsTree())
		if err != nil {
			return err
		}
	}

	return nil
}

package position

import (
	"errors"
	"gno.land/p/gnoswap/deps/tokens/grc721"
	"gno.land/r/gnoswap/gnft"
	"gno.land/r/gnoswap/position"
)

type positionV1 struct {
	store       position.IPositionStore
	nftAccessor NFTAccessor
}

func NewPositionV1(positionStore position.IPositionStore, accessor NFTAccessor) position.IPosition {
	return &positionV1{
		store:       positionStore,
		nftAccessor: accessor,
	}
}

type NFTAccessor interface {
	Approve(_ int, rlm realm, approved address, tid grc721.TokenID) error
	Mint(_ int, rlm realm, to address, tid grc721.TokenID) grc721.TokenID
	Burn(_ int, rlm realm, tid grc721.TokenID)
	TotalSupply() int64
	Exists(tid grc721.TokenID) bool
	OwnerOf(tid grc721.TokenID) (address, error)
}

type gnftAccessor struct{}

func (n *gnftAccessor) Approve(_ int, rlm realm, approved address, tid grc721.TokenID) error {
	if !rlm.IsCurrent() {
		return errors.New(errSpoofedRealm)
	}

	return gnft.Approve(cross(rlm), approved, tid)
}

func (n *gnftAccessor) Mint(_ int, rlm realm, to address, tid grc721.TokenID) grc721.TokenID {
	if !rlm.IsCurrent() {
		panic(errors.New(errSpoofedRealm))
	}

	return gnft.Mint(cross(rlm), to, tid)
}

func (n *gnftAccessor) Burn(_ int, rlm realm, tid grc721.TokenID) {
	if !rlm.IsCurrent() {
		panic(errors.New(errSpoofedRealm))
	}

	gnft.Burn(cross(rlm), tid)
}

func (n *gnftAccessor) TotalSupply() int64 {
	return gnft.TotalSupply()
}

func (n *gnftAccessor) Exists(tid grc721.TokenID) bool {
	return gnft.Exists(tid)
}

func (n *gnftAccessor) OwnerOf(tid grc721.TokenID) (address, error) {
	return gnft.OwnerOf(tid)
}

func newGNFTAccessor() NFTAccessor {
	return &gnftAccessor{}
}

