	if tier == 0 {
		return []string{}
	}

	pools := make([]string, 0)
	s.getPoolTier().membership.Iterate("", "", func(poolPath string, value any) bool {
		currentTier, ok := value.(uint64)
		if !ok {
			panic("failed to cast tier to uint64")
		}
		if currentTier == tier {
			pools = append(pools, poolPath)
		}
		return false
	})

	return pools
