	pool := s.getPoolByPoolPath(poolPath)
	historicalTick := pool.HistoricalTick()

	ticks := make([]int32, 0)
	historicalTick.IterateByOffset(offset, count, func(_ int64, value any) bool {
		tickId, ok := value.(int32)
		if !ok {
			return false
		}
		ticks = append(ticks, tickId)
		return false
	})

	return ticks
