	proposals := gv.store.GetProposals()
	size := proposals.Size()

	if offset >= size {
		return []int64{}
	}

	end := offset + count
	if end > size {
		end = size
	}

	ids := make([]int64, 0, end-offset)
	proposals.IterateByOffset(offset, end-offset, func(key string, value any) bool {
		proposal := value.(*governance.Proposal)
		ids = append(ids, proposal.ID())
		return false
	})

	return ids
